import { validateSuite, inspectSuite, checkReference, gradeTrial, summarizeRun, reportMarkdown, validateRun } from './eval-engine.mjs';

const $ = selector => document.querySelector(selector);
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone = value => structuredClone(value);
const storageKey = 'pmstack-eval-studio-v1';
const steps = ['The framework', 'Define success', 'Design tasks', 'Set the environment', 'Choose graders', 'Plan the trials', 'Run and learn'];
const kinds = {
  model: ['Single-response model', 'Judge the returned answer against the task. Fix the prompt, model version, and sampling settings when comparing runs.'],
  'coding-agent': ['Coding agent', 'Observe working software and test results in a clean repository. Accept different implementations that satisfy the same contract.'],
  'conversational-agent': ['Conversational agent', 'Check resolution in the service system and the quality of the conversation. Keep the simulated customer and policy consistent.'],
  'research-agent': ['Research agent', 'Judge whether claims are supported and the decision is useful. Pin source snapshots for comparisons; separately test fresh information.'],
  'computer-use-agent': ['Computer-use agent', 'Inspect the application’s final state. A screenshot or confirmation sentence alone may not prove the action succeeded.'],
  'long-running-agent': ['Long-running agent or teammate', 'Test a sequence of sessions with controlled memory. Reset between trials; preserve only the intended context within each trial.']
};
const terms = {
  'Evaluation': ['A repeatable test of whether an AI system meets a defined expectation.', 'Use it to turn product judgment into evidence before and after a change. It complements customer research and production monitoring.'],
  'Task': ['One test case with inputs and clear success criteria.', 'Make it demanding for the right reason: it should expose a capability that produces customer value, not depend on a hidden trick.'],
  'Trial': ['One attempt by the target to complete a task.', 'Repeat trials because behavior varies. Keep starting conditions comparable so leftover state does not explain the result.'],
  'Grader': ['A method that scores an aspect of a trial.', 'Use code for observable facts, a model for structured judgment, and people to calibrate or review difficult decisions.'],
  'Transcript': ['The recorded outputs, tool interactions, and intermediate results of a trial.', 'Use available records to investigate failures. Do not require private reasoning that your target does not expose.'],
  'Outcome': ['The final state left behind after the trial.', 'Check the reservation, saved artifact, or resolved issue itself. An agent saying “done” is a claim, not state verification.'],
  'Evaluation harness': ['The infrastructure that sets up trials, runs a target, gathers evidence, applies graders, and combines results.', 'It must distinguish a broken test environment from poor agent performance. pmstack provides this orchestration through adapters.'],
  'Agent harness': ['The runtime that lets a model use tools, context, and memory to act as an agent.', 'It is part of the target. Changing its tools or memory can change performance even if the model stays the same.'],
  'Evaluation suite': ['A collection of tasks that tests related capabilities or protects existing behavior.', 'Include situations where the behavior should happen and where it should not. Inspect slices instead of trusting only an average.'],
  'Reference solution': ['An example of work that meets a task’s success criteria.', 'Use it to test your graders and show the task is feasible. A valid alternative should also pass; do not turn one answer into the only answer.'],
  'Calibration': ['Checking that a grader agrees with informed human judgment.', 'Review both good and bad results, resolve disagreements, and repeat after rubric or model changes.'],
  'Capability and regression': ['Capability tests expose what is not yet reliable. Regression tests protect behavior that already works.', 'Keep both. When a capability suite becomes easy, retain it for protection and add harder customer-relevant tasks.']
};
let step = 0, selectedTask = 0, referenceResult = null, run = null, saved = true;
let library = [];
let reviewNotes = {};
let suite = blankSuite();

function blankSuite() {
  return {schemaVersion:1,id:'my-evaluation',name:'Untitled evaluation',example:false,
    target:{kind:'model',description:'',version:''},product:{customer:'',job:'',success:''},purpose:'capability',
    environment:{description:'',mode:'pinned',reset:'fresh-trial',context:'',tools:[],memory:'No memory carried between trials.',dependencies:'',constraints:''},
    plan:{trials:3,k:3,mix:'balanced',rationale:'',passRateThreshold:0.9},tasks:[]};
}
function newTask() {
  let n = suite.tasks.length + 1;
  while(suite.tasks.some(t => t.id === `task-${n}`)) n++;
  return {id:`task-${n}`,name:`Task ${n}`,prompt:'',context:'',successCriteria:'',category:'positive',difficulty:'',customerValue:'',weight:1,critical:false,
    reference:{description:'',output:'',outcome:{}},graders:[]};
}
function task() { return suite.tasks[selectedTask]; }
function readiness() {
  try { return inspectSuite(suite); }
  catch(error) { return {ready:false,issues:[{level:'error',message:error.message}],taskCount:suite.tasks.length,plannedTrials:suite.tasks.length*suite.plan.trials}; }
}
function persist() {
  try { localStorage.setItem(storageKey, JSON.stringify({suite,step,selectedTask})); }
  catch { saved = false; toast('Browser storage is unavailable. Export your suite to keep it.'); }
}
function changed() { run = null; reviewNotes = {}; referenceResult = null; persist(); }
function toast(message) {
  $('#toast').textContent = message; $('#toast').classList.add('visible');
  clearTimeout(toast.timer); toast.timer = setTimeout(() => $('#toast').classList.remove('visible'), 4500);
}
function download(name, content, type = 'application/json') {
  const url = URL.createObjectURL(new Blob([content], {type}));
  const a = document.createElement('a'); a.href = url; a.download = name; a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
function dialog(title, content, submit, label = 'Save') {
  const node = $('#dialog');
  node.innerHTML = `<form><header><h2>${escape(title)}</h2><button type="button" data-close aria-label="Close dialog">×</button></header>${content}<p role="alert" class="form-error"></p><footer><button type="button" class="button" data-close>Cancel</button><button class="button primary" type="submit">${label}</button></footer></form>`;
  node.querySelectorAll('[data-close]').forEach(b => b.onclick = () => node.close());
  node.querySelector('form').onsubmit = e => {
    e.preventDefault();
    try { submit(new FormData(e.target)); node.close(); }
    catch(error) { node.querySelector('.form-error').textContent = error.message; }
  };
  node.showModal();
}
function field(label, path, value, help = '', rows = 0, type = 'text') {
  const id = `field-${path.replaceAll('.', '-')}`;
  return `<label class="field" for="${id}"><span>${label}</span>${rows ? `<textarea id="${id}" data-field="${path}" rows="${rows}" maxlength="20000">${escape(value)}</textarea>` : `<input id="${id}" data-field="${path}" type="${type}" value="${escape(value)}" ${type==='number'?'min="0" step="any"':''} maxlength="2000">`}${help?`<small>${help}</small>`:''}</label>`;
}
function select(label, path, value, options, help = '') {
  const id = `field-${path.replaceAll('.', '-')}`;
  return `<label class="field" for="${id}"><span>${label}</span><select id="${id}" data-field="${path}">${options.map(([v,l]) => `<option value="${v}" ${v===value?'selected':''}>${l}</option>`).join('')}</select>${help?`<small>${help}</small>`:''}</label>`;
}
function heading(number, title, description) {
  return `<div class="page-heading"><div class="eyebrow">${number} / ${number==='Start here'?'The craft of evaluation':'Your evaluation, step by step'}</div><h1>${title}</h1><p>${description}</p></div>`;
}
function callout(title, content, type='') { return `<aside class="callout ${type}"><span class="callout-symbol">◇</span><div><strong>${title}</strong><p>${content}</p></div></aside>`; }
function termLink(name) { return `<button class="term-link" data-term="${name}">${name} <span>?</span></button>`; }
function taskPicker() {
  return `<div class="task-picker"><label for="task-picker">Working on</label><select id="task-picker">${suite.tasks.map((t,i) => `<option value="${i}" ${selectedTask===i?'selected':''}>${escape(t.name)}</option>`).join('')}</select><button class="button small" data-action="add-task">+ Add task</button></div>`;
}
function continueButton() {
  return `<div class="step-footer"><button class="button" data-step="${Math.max(0,step-1)}">← ${step===1?'The framework':'Previous step'}</button>${step<6?`<button class="button primary" data-step="${step+1}">${steps[step+1]} →</button>`:'<button class="button primary" data-action="export">Export evaluation suite ↓</button>'}</div>`;
}
function render() {
  const status = readiness();
  $('#app').innerHTML = `<aside class="sidebar"><a class="brand" href="./"><span class="brand-icon">▰<br>▰<br>▰</span>pmstack<span class="brand-caption">Evaluation studio</span></a><div class="nav-caption">From judgment to evidence</div><nav aria-label="Evaluation workflow">${steps.map((name,i) => `<button data-step="${i}" class="nav-step ${step===i?'active':''}" ${step===i?'aria-current="step"':''}><span>${i===0?'◎':String(i).padStart(2,'0')}</span>${name}</button>`).join('')}</nav><div class="sidebar-note"><span>THE PM’S CONTRIBUTION</span><p>Know what good means.<br>Make the test earn your trust.</p></div><div class="sidebar-bottom"><button data-action="library">Browse example library <span>↗</span></button><button data-action="glossary">Terms in plain English <span>↗</span></button><a href="https://github.com/RyanAlberts/pmstack">Source & templates <span>↗</span></a><small>${saved?'Draft saved in this browser':'Export to save your work'}</small></div></aside><div class="workspace"><header class="topbar"><div><span class="workspace-dot"></span>${step===0?'A practical guide to agent evaluations':escape(suite.name)}${suite.example&&step!==0?'<span class="example-label">Illustrative example</span>':''}</div><div class="top-actions"><button class="button small" data-action="new">New suite</button><button class="button small" data-action="import">Import</button><button class="button small" data-action="export">Export suite ↓</button></div></header><main id="main" tabindex="-1">${[frameworkView,successView,tasksView,environmentView,gradersView,trialsView,runView][step](status)}${step?continueButton():''}</main><footer class="site-footer"><a href="https://www.anthropic.com/engineering/demystifying-evals-for-ai-agents">Built around Anthropic’s evaluation taxonomy ↗</a><span>Your tools. Your evidence. Your judgment.</span></footer></div>`;
}
function frameworkView() {
  return `<section class="framework-intro"><div class="hero-copy"><div class="eyebrow">Evaluations for product managers</div><h1>Your job is to<br>define <em>success.</em></h1><p class="hero-lead">An agent can sound right and still do the wrong thing. An evaluation makes your expectations testable, so you can see what works, what changed, and what deserves your trust.</p><div class="hero-actions"><button class="button primary large" data-action="start">Define my evaluation <span>→</span></button><button class="text-button" data-action="library">Explore clearly labeled examples ↗</button></div><div class="hero-footnote">No account. No model calls from this page. A framework you can take to your own agent.</div></div><div class="principle-card"><span class="eyebrow">Start with the customer</span><h2>What would a good result<br>make possible?</h2><p>Write that expectation before choosing a metric. Then decide what evidence would convince you it happened.</p><div class="principle-divider"></div><div class="principle-row"><span>01</span><p><strong>Define the destination.</strong><br>A useful, observable result.</p></div><div class="principle-row"><span>02</span><p><strong>Make the task fair.</strong><br>Clear context. Real constraints.</p></div><div class="principle-row"><span>03</span><p><strong>Test the test.</strong><br>Good work passes. False success does not.</p></div></div></section><section class="framework-map"><div class="section-heading"><div><span class="eyebrow">The framework comes first</span><h2>One evaluation. Four things to understand.</h2></div><span class="section-note">Click a term to explore the tradeoff.</span></div><div class="flow"><article><span class="flow-number">01 / Define</span><h3>${termLink('Task')}</h3><p>A clear request, its context, and the conditions for success.</p><div class="mini-tags"><span>Environment</span><span>Tools</span><span>Memory</span></div></article><span class="flow-arrow">→</span><article><span class="flow-number">02 / Attempt</span><h3>${termLink('Trial')}</h3><p>The model or agent tries the task. Repeat from controlled starting conditions.</p><div class="mini-tags"><span>Same task</span><span>Fresh attempt</span></div></article><span class="flow-arrow">→</span><article><span class="flow-number">03 / Observe</span><h3>${termLink('Outcome')}</h3><p>What actually changed. Keep the transcript to understand how it happened.</p><div class="mini-tags"><span>Final state</span><span>Evidence</span></div></article><span class="flow-arrow">→</span><article><span class="flow-number">04 / Judge</span><h3>${termLink('Grader')}</h3><p>Code, a model, or a person assesses the evidence against your expectations.</p><div class="mini-tags"><span>Score</span><span>Reason</span><span>Uncertainty</span></div></article></div><div class="map-footer"><span>${termLink('Evaluation harness')} coordinates the loop.</span><span>${termLink('Agent harness')} is part of the system you test.</span></div></section><section class="why-grid"><article><span>Before building</span><h3>Make requirements concrete.</h3><p>Turn “helpful” into an outcome two informed reviewers can agree on.</p></article><article><span>Before changing</span><h3>Compare on the same ground.</h3><p>Find improvements and regressions while checking whether the test stayed fair.</p></article><article><span>After shipping</span><h3>Keep learning from real failures.</h3><p>Add customer cases, audit grades, and create harder tasks as capabilities improve.</p></article></section>${libraryView()}`;
}
function libraryView() {
  return `<section id="example-library" class="library"><div class="section-heading"><div><div class="eyebrow">Examples, not the framework</div><h2>Start with a familiar job.</h2><p>Every starter is illustrative. Replace its tasks, context, and reference evidence before making claims about your product.</p></div></div><div class="library-grid">${library.map((s,i) => `<button class="library-card" data-example="${i}"><span class="library-type">${escape(kinds[s.target.kind]?.[0]||s.target.kind)} <span>↗</span></span><h3>${escape(s.name)}</h3><p>${escape(s.product.job)}</p><div><span class="example-label">Example template</span><small>${s.tasks.length} tasks</small></div></button>`).join('')}</div></section>`;
}
function successView() {
  return heading('01','What does success mean?','Start with the person the system serves, the job they need done, and the evidence of a useful result.')+`<div class="editor-grid"><section class="panel"><h2>The product promise</h2>${field('Name your evaluation','name',suite.name,'Use the customer job, not only the model name.')}${select('What are you evaluating?','target.kind',suite.target.kind,Object.entries(kinds).map(([k,v])=>[k,v[0]]))}${field('Who is the customer?','product.customer',suite.product.customer,'Who feels the cost of a wrong result?')}${field('What job do they need done?','product.job',suite.product.job,'Describe the work in their words.',3)}${field('What would a successful result look like?','product.success',suite.product.success,'Name an observable outcome and the tradeoffs that matter.',3)}</section><aside class="teaching-column">${callout('For your target',escape(kinds[suite.target.kind][1]))}<section class="panel secondary"><h3>Define the system boundary</h3>${field('Target description','target.description',suite.target.description,'For an agent: model + runtime + tools + memory.',3)}${field('Version or configuration','target.version',suite.target.version,'Record enough detail to repeat a comparison.')}${select('Why are you running this suite?','purpose',suite.purpose,[['capability','Discover and improve capabilities'],['regression','Protect behavior that already works']])}<p class="teaching-text">A capability suite should leave room to improve. A regression suite protects work the system already does reliably.</p></section></aside></div>`;
}
function tasksView() {
  const t = task();
  return heading('02','Give good judgment a fair test.','A task should be clear enough to solve and challenging enough to reveal customer value.')+`${taskPicker()}${!t?`<section class="empty panel"><h2>Start with one real task.</h2><p>Use a manual check, customer issue, or product requirement. Add a nearby case where the same action would be wrong.</p><button class="button primary" data-action="add-task">Add my first task</button></section>`:`<div class="editor-grid"><section class="panel"><div class="panel-header"><h2>The task specification</h2><button class="text-button danger" data-action="remove-task">Remove task</button></div>${field('Task name','task.name',t.name)}${field('The request given to the target','task.prompt',t.prompt,'Everything the grader requires must follow from this request and its supplied context.',4)}${field('Context available for this task','task.context',t.context,'Relevant policy, prior conversation, known facts, or starting state.',3)}${field('Success criteria','task.successCriteria',t.successCriteria,'State what must be true at the end. Allow valid alternative approaches.',4)}${field('Why this matters to the customer','task.customerValue',t.customerValue,'What benefit or avoided harm distinguishes a useful success?',2)}${field('What makes this task challenging?','task.difficulty',t.difficulty,'Competing constraints, missing information, multiple tools, or a difficult judgment.',2)}<div class="two-fields">${select('Case type','task.category',t.category,[['positive','Should perform the behavior'],['negative','Should not perform the behavior'],['edge','Boundary or unusual condition'],['adversarial','Attempt to mislead or bypass']])}${field('Sampling weight','task.weight',t.weight,'Use measured prevalence for production weighting.',0,'number')}</div><label class="check-field"><input type="checkbox" data-field="task.critical" ${t.critical?'checked':''}><span>A failure on this task must block the suite, regardless of its average.</span></label></section><aside class="teaching-column"><section class="panel secondary"><span class="eyebrow">Test the test</span><h3>${termLink('Reference solution')}</h3><details class="reference-guide"><summary>Choose the right kind of reference</summary><p><strong>Exact answer:</strong> use when one result or format is explicitly required.</p><p><strong>Valid end state:</strong> prefer observable constraints when multiple approaches work.</p><p><strong>Working implementation:</strong> run it in the same environment to prove a coding task is feasible.</p><p><strong>Reviewed examples and rubric:</strong> use for judgment. Include good alternatives and polished failures; do not demand one wording.</p><p>This form stores a proposed output and state. Execute working references outside the browser and retain their evidence.</p></details>${field('Why this reference is valid','task.reference.description',t.reference.description,'An expert should be able to reproduce a result that meets the specification.',3)}${field('Reference output','task.reference.output',t.reference.output,'A message, artifact description, or answer. It need not be the only valid wording.',3)}<label class="field"><span>Reference outcome as JSON</span><textarea data-json="reference" rows="8" spellcheck="false">${escape(JSON.stringify(t.reference.outcome,null,2))}</textarea><small>The final state your observer would report. JSON is a plain text format for structured data.</small></label><p class="teaching-text">A reference passing code checks proves those checks accept that state. It does not prove the environment is solvable or a real agent achieved it.</p></section>${callout('A useful fairness test','Could two domain experts solve this task and agree on the verdict? If a hidden filename, rounding rule, or tool order determines the result, fix the specification or grader.')}</aside></div>`}`;
}
function environmentView() {
  return heading('03','Control the starting conditions.','Make a low score explain the agent’s performance, rather than yesterday’s files, stale data, or a broken dependency.')+`<div class="editor-grid"><section class="panel"><h2>The world the target works in</h2>${field('Environment description','environment.description',suite.environment.description,'Repository, browser, ticket system, test account, or another workspace.',3)}${field('Shared context','environment.context',suite.environment.context,'Information available in every task: policies, instructions, time, permissions.',3)}<label class="field"><span>Tools available to the target</span><textarea data-tools rows="3">${escape(suite.environment.tools.join('\n'))}</textarea><small>One tool per line. Match production capabilities without giving the target access to answer keys.</small></label>${field('Dependencies and versions','environment.dependencies',suite.environment.dependencies,'Pin data snapshots, application versions, simulated users, and clocks where relevant.',3)}${field('Allowed actions and limits','environment.constraints',suite.environment.constraints,'Which real-world actions must remain in a sandbox? What requires approval?',3)}</section><aside class="teaching-column"><section class="panel secondary">${select('Environment strategy','environment.mode',suite.environment.mode,[['pinned','Pinned and repeatable'],['live','Live and changing']])}<p class="teaching-text">Pinned environments make comparisons easier. Live environments reveal freshness and integration failures, but their changes can confound scores. Keep those results separate.</p>${select('Trial reset strategy','environment.reset',suite.environment.reset,[['fresh-trial','Fresh state for every trial'],['session-sequence','A session sequence inside each fresh trial']])}${field('Memory policy','environment.memory',suite.environment.memory,'What is seeded, retained within a trial, and cleared before the next trial?',4)}</section>${callout('For long-running teammates','Treat several sessions as one trial when testing memory. Seed a known snapshot, change a fact or preference deliberately, then inspect what was retained. Do not let earlier trial answers leak into later ones.')}${callout('Observe separately','The target executes the work. A separately configured observer reads final state. A temporary folder reduces accidental state leakage; it is not a security sandbox.')}</aside></div>`;
}
function gradersView() {
  const t = task();
  return heading('04','Choose evidence that is hard to fake.','A grader measures a specific part of success. Combine clear checks without averaging away a critical failure.')+`<div class="grader-types"><article><span class="type-mark">{ }</span><h3>Code</h3><p>Repeatable checks of state, tests, numbers, or exact requirements.</p><small>Fast and precise. Brittle if it mistakes one valid format for the goal.</small></article><article><span class="type-mark">✧</span><h3>Model</h3><p>A separate model applies a structured scoring rubric to evidence.</p><small>Scales nuanced judgment. Can vary, favor style, or follow injected instructions.</small></article><article><span class="type-mark">◎</span><h3>Human</h3><p>An informed person reviews the result against an explicit standard.</p><small>Useful for taste and calibration. Reviewers still disagree and need examples.</small></article></div>${taskPicker()}${!t?callout('Create a task first','Graders belong to a task, so each check can trace back to a stated requirement.'):`<div class="editor-grid"><section><div class="grader-list">${t.graders.map((g,i)=>`<article class="panel grader-card"><div class="panel-header"><div><span class="eyebrow">${escape(g.type)} grader · ${escape(g.source)}</span><h3>${escape(g.name)}</h3></div><button class="text-button" data-edit-grader="${i}">Edit</button></div><p>${escape(g.rubric||'Checks the specified evidence field.')}</p>${g.type==='code'?`<code>${escape(g.check?.path||'(whole value)')} ${escape(g.check?.operator)} ${escape(JSON.stringify(g.check?.expected??''))}</code>`:`<small>Calibration: ${escape(g.calibration||'Not yet defined')}</small>`}<div class="grader-meta"><span>${g.required?'Required to pass':'Contributes partial credit'}</span><span>Threshold ${g.threshold} / 1</span><button class="text-button danger" data-remove-grader="${i}">Remove</button></div></article>`).join('')||'<div class="panel empty"><h3>No graders yet.</h3><p>Start with one observable requirement. Add judgment only where a fact check is insufficient.</p></div>'}</div><button class="button primary" data-action="add-grader">+ Add a grader</button></section><aside class="teaching-column">${callout('Grade the outcome, not an arbitrary route','Inspect final state and useful output. Use transcript checks for real safety boundaries or interaction requirements, not a prescribed sequence of clicks.')}<section class="panel secondary"><span class="eyebrow">Try your grading logic</span><h3>Would your test catch false success?</h3><p class="teaching-text">Run the code checks on the reference state, then on a claim of success with no observed outcome. No agent is called.</p><div class="button-stack"><button class="button" data-action="reference">Check reference evidence</button><button class="button" data-action="false-success">Check an unsupported “done”</button></div>${referenceResult?`<div class="reference-result"><strong>${referenceResult.label}</strong>${referenceResult.result.grades.map(g=>`<div class="grade-row"><span class="status ${g.status}">${g.status}</span><div><strong>${escape(g.name)}</strong><p>${escape(g.reason)}</p></div></div>`).join('')}<small>Model and human judgments remain unresolved without an actual grader response.</small></div>`:''}</section></aside></div>`}`;
}
function trialsView(status) {
  const counts = Object.fromEntries(['positive','negative','edge','adversarial'].map(c=>[c,suite.tasks.filter(t=>t.category===c).length]));
  const p = 0.75, k = Math.max(1,Math.min(100,Number(suite.plan.k)||1));
  return heading('05','Measure reliability, not a lucky attempt.','Choose the task mix and repeat count before running. Keep conditions and graders comparable across versions.')+`<div class="editor-grid"><section class="panel"><h2>Your experiment plan</h2><div class="two-fields">${field('Trials per task','plan.trials',suite.plan.trials,'Each trial starts from a fresh environment.',0,'number')}${field('Attempts in the reliability estimate (k)','plan.k',suite.plan.k,'Use a retry count that matches the product.',0,'number')}</div>${select('How should tasks contribute?','plan.mix',suite.plan.mix,[['balanced','Balance the decision boundaries'],['production-weighted','Weight tasks by actual usage']])}${field('Why this mix and repeat count?','plan.rationale',suite.plan.rationale,'Explain the decision you need to make, likely errors, and remaining uncertainty.',3)}${field('Minimum pass rate for this suite','plan.passRateThreshold',suite.plan.passRateThreshold,'0 to 1. Missing judgments or invalid trials still prevent a clean pass.',0,'number')}<div class="mix-grid">${Object.entries(counts).map(([c,n])=>`<div><strong>${n}</strong><span>${c==='positive'?'Should act':c==='negative'?'Should not act':c==='edge'?'Boundary cases':'Adversarial'}</span></div>`).join('')}</div><p class="teaching-text">Balanced sets expose both overuse and underuse of a behavior. Production weights estimate the workload you actually see. Report each slice so common easy cases cannot hide rare harm.</p></section><aside class="teaching-column"><section class="panel secondary"><span class="eyebrow">An illustration, not your score</span><h3>One success is not consistent success.</h3><p class="teaching-text">Suppose a task succeeds 75% of the time. With ${k} independent attempts:</p><div class="metric-demo"><div><strong>${((1-(1-p)**k)*100).toFixed(1)}%</strong><span>At least one succeeds</span><small>pass@${k}</small></div><div><strong>${(p**k*100).toFixed(1)}%</strong><span>Every attempt succeeds</span><small>pass^${k}</small></div></div><p class="teaching-text">Both are estimates. Correlated failures, changing conditions, or too few trials make them less informative. More retries do not fix a broken grader.</p></section>${callout('Capability or regression?',suite.purpose==='capability'?'Leave room for meaningful improvement. If every solvable task passes easily, add harder customer-relevant work and keep the old tasks as regression protection.':'Protect known behavior with stable cases. Investigate new failures before changing the threshold or removing a difficult case.')}</aside></div><section class="panel readiness"><div class="panel-header"><h2>Evaluation design checks</h2><span class="status ${status.ready?'pass':'unknown'}">${status.ready?'Structurally ready':'Needs attention'}</span></div><p>These checks catch missing structure. They cannot certify the task’s usefulness, fairness, or resistance to manipulation.</p>${issueList(status.issues)}<div class="planned-count">${suite.tasks.length} tasks × ${suite.plan.trials} trials = <strong>${suite.tasks.length*suite.plan.trials} planned attempts</strong></div></section>`;
}
function issueList(issues = []) {
  return issues.length?`<ul class="issue-list">${issues.map(i=>`<li><span>${i.level==='error'?'!':'○'}</span><div>${escape(i.message)}${i.taskId?` <small>(${escape(i.taskId)})</small>`:''}</div></li>`).join('')}</ul>`:'<p class="teaching-text">No structural issues found. Validate reference solutions and inspect real transcripts before trusting scores.</p>';
}
function runView(status) {
  return heading('06','Run the target. Then question the score.','Export your suite, connect an adapter to your system, and bring the trial evidence back here.')+`<div class="run-steps"><article><span>1</span><h3>Export the suite</h3><p>Your tasks, environment contract, references, and graders travel together as JSON.</p><button class="button primary" data-action="export">Download suite ↓</button></article><article><span>2</span><h3>Connect your target</h3><p>A local adapter calls your model or agent. Setup and observation use separate commands.</p><a class="button" href="https://github.com/RyanAlberts/pmstack/blob/main/docs/eval-adapters.md">Adapter guide ↗</a></article><article><span>3</span><h3>Inspect the results</h3><p>Import the harness result. Examine actual state, transcripts, graders, and invalid trials.</p><button class="button" data-action="import-run">Import run evidence ↑</button></article></div><details class="terminal" open><summary>The same workflow in your terminal</summary><pre>node bin/eval-harness.mjs validate ${escape(suite.id)}.json
node bin/eval-harness.mjs run ${escape(suite.id)}.json --adapter adapters.json --output run-1
node bin/eval-harness.mjs report run-1/run.json</pre><p>Node.js 20 or later. The browser does not execute adapters or call a model. Provider usage belongs to your configured account.</p></details>${run?runResults():`<section class="panel empty"><span class="empty-symbol">◎</span><h2>No agent run has been imported.</h2><p>Reference checks are not agent trials. Your results belong here after the target has actually attempted the tasks.</p><button class="button" data-action="sample-run">Inspect a recorded simulation →</button><p class="teaching-text">Example only: a local support simulation claims success without fixing the problem. No live AI model was called. Opening it replaces the current draft.</p>${!status.ready?'<button class="text-button" data-step="5">Review the design checks first →</button>':''}</section>`}<section class="learning-loop"><h2>When something fails, find out what failed.</h2><div class="why-grid"><article><span>The agent</span><h3>It missed a clear expectation.</h3><p>Keep the task. Improve the target, rerun it, and check that other behavior did not regress.</p></article><article><span>The evaluation</span><h3>The test rejected good work.</h3><p>Fix ambiguity, references, environment failures, or a brittle grader. Re-establish the baseline after the change.</p></article><article><span>The evidence</span><h3>You cannot tell yet.</h3><p>Inspect the transcript and observed outcome. Missing evidence stays unresolved; it is never a quiet pass.</p></article></div></section>`;
}
function runResults() {
  const summary = summarizeRun(run.suite,run.trials);
  const pct = n => typeof n==='number'?`${(n*100).toFixed(1)}%`:'Unresolved';
  return `<section class="panel results"><div class="panel-header"><div><span class="eyebrow">Imported run · Source authenticity not independently verified</span><h2>${escape(run.suite.name)}</h2></div><div class="top-actions"><button class="button" data-action="export-run">Save reviewed run ↓</button><button class="button" data-action="report">Download report ↓</button></div></div><div class="results-metrics"><div><span>Overall status</span><strong class="${summary.status}">${escape(summary.status)}</strong></div><div><span>Equal task average</span><strong>${pct(summary.macroPassRate)}</strong></div><div><span>Invalid trials</span><strong>${summary.invalid}</strong></div><div><span>Unknown / missing</span><strong>${summary.unknown} / ${summary.missing}</strong></div></div><p class="teaching-text">The suite gate uses the ${run.suite.plan.mix==='production-weighted'?'production-weighted':'equal-task'} average against ${(run.suite.plan.passRateThreshold*100).toFixed(0)}%. The weighted average is ${pct(summary.weightedPassRate)}; the raw trial pass rate is ${pct(summary.passRate)}.</p>${summary.criticalFailed.length?callout('Critical task failures block this suite',escape(summary.criticalFailed.join(', '))):''}<p class="teaching-text">Invalid trials diagnose the evaluation infrastructure. They do not count as agent failures or successes. Missing and unresolved trials block a clean result.</p><div class="result-table"><div class="result-row table-head"><span>Task</span><span>Pass rate</span><span>At least one / all ${summary.k}</span></div>${summary.byTask.map(t=>`<div class="result-row"><span>${escape(t.name)}</span><strong>${pct(t.passRate)}</strong><span>${pct(t.estimatedPassAtK)} / ${pct(t.estimatedPassPowerK)}</span></div>`).join('')}</div><p class="teaching-text">${escape(typeof summary.assumptions==='string'?summary.assumptions:JSON.stringify(summary.assumptions))}</p><h3>Case mix results</h3><div class="result-table">${Object.entries(summary.slices.category).map(([category,slice])=>`<div class="result-row"><span>${escape(category)}</span><strong>${pct(slice.passRate)}</strong><span>${slice.valid} graded · ${slice.unknown} unknown · ${slice.invalid} invalid</span></div>`).join('')}</div><h3>Inspect individual trials</h3>${run.trials.map((t,i)=>`<details class="trial"><summary><span>${escape(t.taskId)} · Trial ${escape(t.trial??i+1)}</span><span class="status ${escape(t.status)}">${escape(t.status)}</span></summary><div class="trial-detail"><h4>Output</h4><pre>${escape(typeof t.output==='string'?t.output:JSON.stringify(t.output,null,2))}</pre><h4>Observed outcome</h4><pre>${escape(JSON.stringify(t.outcome??null,null,2))}</pre><h4>Grader results</h4>${(t.grades||[]).map(g=>`<div class="grade-row"><span class="status ${escape(g.status)}">${escape(g.status)}</span><div><strong>${escape(g.name||g.id)}</strong><p>${escape(g.reason)}</p></div></div>`).join('')}${run.suite.tasks.find(x=>x.id===t.taskId).graders.some(g=>g.type==='human')?`<button class="button small" data-human-grade="${i}">Record human grade</button>`:''}<button class="button small" data-diagnose="${i}">Diagnose this trial</button>${reviewNotes[i]?`<div class="callout"><p><strong>${escape(reviewNotes[i].cause)}</strong><br>${escape(reviewNotes[i].reason)}<br>Next: ${escape(reviewNotes[i].next)}</p></div>`:''}<h4>Transcript</h4><pre>${escape(JSON.stringify(t.transcript??[],null,2))}</pre>${t.errors?.length?`<h4>Execution or infrastructure errors</h4><pre>${escape(JSON.stringify(t.errors,null,2))}</pre>`:''}</div></details>`).join('')}</section>`;
}
function editGrader(index) {
  const t = task(); if(!t) return;
  let graderNumber=t.graders.length+1;while(t.graders.some(g=>g.id===`grader-${graderNumber}`))graderNumber++;
  const g = index===null?{id:`grader-${graderNumber}`,name:'',type:'code',source:'outcome',required:true,weight:1,threshold:1,check:{operator:'equals',path:'',expected:true},rubric:'',calibration:''}:t.graders[index];
  dialog(index===null?'Add a grader':'Edit grader',`<p class="dialog-intro">Tie this check to a stated success criterion. Keep answer keys and grader instructions outside the target’s writable environment.</p><label class="field"><span>Grader name</span><input name="name" value="${escape(g.name)}" required></label><div class="two-fields"><label class="field"><span>Grader type</span><select name="type">${['code','model','human'].map(x=>`<option ${g.type===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>Evidence source</span><select name="source">${['outcome','output','transcript'].map(x=>`<option ${g.source===x?'selected':''}>${x}</option>`).join('')}</select></label></div><label class="field"><span>Requirement or scoring rubric</span><textarea name="rubric" rows="3" required>${escape(g.rubric)}</textarea><small>Describe poor, acceptable, and excellent evidence. Tell model graders to return unknown when evidence is missing.</small></label><div class="code-options"><h3>For code graders</h3><div class="two-fields"><label class="field"><span>Operator</span><select name="operator">${['equals','contains','exists','number-range'].map(x=>`<option ${g.check?.operator===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>Evidence field path</span><input name="path" value="${escape(g.check?.path)}" placeholder="reservation.status"><small>Dot-separated fields. Leave blank to check the entire value.</small></label></div><label class="field"><span>Expected value as JSON</span><input name="expected" value="${escape(JSON.stringify(g.check?.expected??true))}"><small>For example: true, 120, or "confirmed". A range uses the minimum and maximum below.</small></label><div class="two-fields"><label class="field"><span>Minimum for range</span><input name="min" type="number" value="${g.check?.min??0}" step="any"></label><label class="field"><span>Maximum for range</span><input name="max" type="number" value="${g.check?.max??1}" step="any"></label></div></div><label class="field"><span>How will you calibrate this grader?</span><textarea name="calibration" rows="2">${escape(g.calibration)}</textarea><small>For judgment graders: compare with expert labels, inspect disagreement, and test wording or position bias.</small></label><div class="two-fields"><label class="field"><span>Passing threshold (0 to 1)</span><input type="number" name="threshold" value="${g.threshold}" min="0" max="1" step="0.05" required></label><label class="field"><span>Weight for partial credit</span><input type="number" name="weight" value="${g.weight}" min="0.1" step="0.1" required></label></div><label class="check-field"><input type="checkbox" name="required" ${g.required?'checked':''}><span>This grader must pass for the task to pass.</span></label>`,data=>{
    const type=data.get('type'), next={id:g.id,name:data.get('name').trim(),type,source:data.get('source'),required:data.has('required'),weight:Number(data.get('weight')),threshold:Number(data.get('threshold')),rubric:data.get('rubric').trim(),calibration:data.get('calibration').trim()};
    if(type==='code') { const operator=data.get('operator'); next.check={operator,path:data.get('path').trim()}; if(['equals','contains'].includes(operator)) next.check.expected=JSON.parse(data.get('expected')); if(operator==='number-range') {next.check.min=Number(data.get('min')); next.check.max=Number(data.get('max')); if(next.check.min>next.check.max) throw Error('Minimum must be no greater than maximum.');} }
    if(!next.name||!next.rubric) throw Error('Name the grader and explain its requirement.');
    if(index===null)t.graders.push(next);else t.graders[index]=next;
    changed();render();
  },'Save grader');
  const update=()=>{ $('#dialog .code-options').hidden=$('#dialog select[name=type]').value!=='code'; };
  $('#dialog select[name=type]').onchange=update;update();
}
function chooseFile(callback) {
  const input=document.createElement('input');input.type='file';input.accept='.json,application/json';
  input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>10_000_000)throw Error('Choose a JSON file smaller than 10 MB.');callback(JSON.parse(await file.text()));}catch(error){toast(`Import failed: ${error.message}`);}};
  input.click();
}
function action(name) {
  if(name==='sample-run'){dialog('Open the recorded example?', '<p>This replaces your current draft with a clearly labeled support simulation. Export your work first to preserve it.</p>', async()=>{try{const response=await fetch('./sample-run.json');if(!response.ok)throw Error('Example record unavailable.');run=validateRun(await response.json());suite=clone(run.suite);selectedTask=0;step=6;reviewNotes={};referenceResult=null;persist();render();toast('Recorded offline simulation loaded. No live model was called.');}catch(error){toast(error.message);}},'Open simulation');return;}
  if(name==='new'||(name==='start'&&suite.example)) {dialog('Start your own evaluation?','<p>This opens a blank framework for your use case. Export the current draft first if you want to keep it.</p>',()=>{suite=blankSuite();step=1;selectedTask=0;changed();render();},'Start a new suite');return;}
  if(name==='start') { step=1;persist();render();return; }
  if(name==='library') { step=0;render();$('#example-library').scrollIntoView({behavior:'smooth'});return; }
  if(name==='glossary') { dialog('The framework in plain English',`<div class="glossary">${Object.entries(terms).map(([n,v])=>`<article><h3>${n}</h3><p>${v[0]}</p><small>${v[1]}</small></article>`).join('')}</div>`,()=>{},'Back to my evaluation');return; }
  if(name==='export') {
    try { validateSuite(suite);download(`${suite.id}.json`,JSON.stringify(suite,null,2));toast('Suite exported. Connect your own target with a separate adapter.'); }
    catch(error){dialog('This draft needs more definition',`<p>${escape(error.message)}</p><p>Your draft stays in this browser. Complete the missing structure before exporting a runnable suite.</p>`,()=>{},'Continue editing');}
    return;
  }
  if(name==='import'||name==='import-run') {
    chooseFile(raw=>{
      const isRun=name==='import-run'||raw.suite;
      const next=validateSuite(isRun?raw.suite:raw);
      if(isRun) {
        if(!Array.isArray(raw.trials)||raw.trials.length>10000)throw Error('A run needs a bounded trials array.');
        for(const t of raw.trials)if(!t||!next.tasks.some(x=>x.id===t.taskId)||!['pass','fail','unknown','invalid'].includes(t.status)||!Array.isArray(t.grades||[]))throw Error('Invalid trial record.');
        summarizeRun(next,raw.trials);
      }
      dialog('Open this evaluation?',`<p>This replaces the current draft in this browser. Export it first if you want to keep it. Imported records are supplied evidence, not authenticated execution.</p>`,()=>{suite=next;run=isRun?validateRun(raw):null;selectedTask=0;step=isRun?6:1;referenceResult=null;reviewNotes={};persist();render();},'Open evaluation');
    });return;
  }
  if(name==='add-task') {suite.tasks.push(newTask());selectedTask=suite.tasks.length-1;changed();render();return;}
  if(name==='remove-task') {dialog('Remove this task?','<p>The task and its graders will be removed from this draft. Export a copy if you want to preserve it.</p>',()=>{suite.tasks.splice(selectedTask,1);selectedTask=Math.max(0,selectedTask-1);changed();render();},'Remove task');return;}
  if(name==='add-grader') {editGrader(null);return;}
  if(name==='reference'||name==='false-success') {
    try {referenceResult={label:name==='reference'?'Reference evidence check':'Unsupported success claim',result:name==='reference'?checkReference(suite,task().id):gradeTrial(suite,task().id,{output:'Done. Everything succeeded.',transcript:[],outcome:null})};render();}
    catch(error){toast(error.message);}return;
  }
  if(name==='export-run'&&run){download(`${run.suite.id}-reviewed-run.json`,JSON.stringify(validateRun(run),null,2));return;}
  if(name==='report'&&run) {download(`${run.suite.id}-report.md`,reportMarkdown(run)+'\n\n## Product review notes\n\n'+Object.entries(reviewNotes).map(([i,n])=>`${run.trials[i].taskId} / trial ${run.trials[i].trial}: ${n.cause}\n${n.reason}\nNext: ${n.next}`).join('\n\n'),'text/markdown');return;}
}
$('#app').addEventListener('click',e=>{
  const button=e.target.closest('button');if(!button)return;
  if(button.dataset.humanGrade!==undefined){const i=Number(button.dataset.humanGrade),row=run.trials[i],graders=run.suite.tasks.find(t=>t.id===row.taskId).graders.filter(g=>g.type==='human');dialog('Record a human judgment',`<p>Read the trial evidence and the grader’s rubric before scoring. This records your assessment; it cannot override failed code checks or infrastructure errors.</p><label class="field"><span>Human grader</span><select name="grader">${graders.map(g=>`<option value="${escape(g.id)}">${escape(g.name)}</option>`).join('')}</select></label>${graders.map(g=>`<div class="callout"><p><strong>${escape(g.name)}</strong><br>${escape(g.rubric)}</p></div>`).join('')}<label class="field"><span>Score (0 to 1)</span><input type="number" name="score" min="0" max="1" step="0.05" required></label><label class="field"><span>Evidence and reasoning</span><textarea name="reason" rows="4" required></textarea></label>`,data=>{const score=Number(data.get('score')),reason=data.get('reason').trim();if(!reason||!Number.isFinite(score)||score<0||score>1)throw Error('Supply a score from 0 to 1 and supporting evidence.');row.graderResults={...row.graderResults,[data.get('grader')]:{score,reason:'Human review entered in the studio: '+reason}};run=validateRun(run);render();toast('Judgment recorded. Save the reviewed run to preserve the evidence.');},'Record grade');}
  else if(button.dataset.diagnose!==undefined){const i=Number(button.dataset.diagnose);dialog('What explains this trial?',`<p>Record your diagnosis without changing the original grade. A grader fix requires a new comparison, not a rewritten score.</p><label class="field"><span>Working diagnosis</span><select name="cause"><option>Agent missed the stated outcome</option><option>Task or reference is ambiguous</option><option>Grader rejected a valid result</option><option>Environment or adapter failed</option><option>Insufficient evidence</option></select></label><label class="field"><span>Evidence for your diagnosis</span><textarea name="reason" required rows="3"></textarea></label><label class="field"><span>Next experiment or correction</span><textarea name="next" required rows="2"></textarea></label>`,data=>{const reason=data.get('reason').trim(),next=data.get('next').trim();if(!reason||!next)throw Error('Record the evidence and next step.');reviewNotes[i]={cause:data.get('cause'),reason,next};render();toast('Diagnosis added to the downloadable report. Original grades are unchanged.');},'Record diagnosis');}
  else if(button.dataset.step!==undefined){step=Number(button.dataset.step);persist();render();$('#main').focus();window.scrollTo(0,0);}
  else if(button.dataset.example!==undefined){const next=library[Number(button.dataset.example)];dialog(`Use the ${next.name} example?`,'<p>This replaces the current draft with clearly labeled illustrative tasks. You can edit every task, reference, and grader.</p>',()=>{suite=clone(next);step=1;selectedTask=0;changed();render();window.scrollTo(0,0);},'Use example template');}
  else if(button.dataset.term){const [definition,tradeoff]=terms[button.dataset.term];dialog(button.dataset.term,`<p class="term-definition">${definition}</p><div class="callout"><p>${tradeoff}</p></div>`,()=>{},'Continue');}
  else if(button.dataset.editGrader!==undefined)editGrader(Number(button.dataset.editGrader));
  else if(button.dataset.removeGrader!==undefined){task().graders.splice(Number(button.dataset.removeGrader),1);changed();render();}
  else if(button.dataset.action)action(button.dataset.action);
});
$('#app').addEventListener('change',e=>{
  try {
    if(e.target.id==='task-picker'){selectedTask=Number(e.target.value);referenceResult=null;persist();render();return;}
    if(e.target.dataset.json){const value=JSON.parse(e.target.value);if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Reference outcome must be a JSON object.');task().reference.outcome=value;}
    else if(e.target.hasAttribute('data-tools'))suite.environment.tools=e.target.value.split('\n').map(s=>s.trim()).filter(Boolean);
    else if(e.target.dataset.field){const path=e.target.dataset.field.split('.');let target=path[0]==='task'?(path.shift(),task()):suite;while(path.length>1)target=target[path.shift()];target[path[0]]=e.target.type==='checkbox'?e.target.checked:e.target.type==='number'?Number(e.target.value):e.target.value;}
    else return;
    changed();
    if(['target.kind','purpose','plan.k','plan.trials','plan.mix'].includes(e.target.dataset.field))render();
  }catch(error){toast(error.message);e.target.setAttribute('aria-invalid','true');}
});
try {
  const response=await fetch('./eval-library.json');if(!response.ok)throw Error('The example library could not load.');
  library=(await response.json()).map(validateSuite);
  try {const state=JSON.parse(localStorage.getItem(storageKey)||'null');if(state&&state.suite?.schemaVersion===1&&Array.isArray(state.suite.tasks)){suite=state.suite;step=Math.max(0,Math.min(6,Number(state.step)||0));selectedTask=Math.max(0,Math.min(suite.tasks.length-1,Number(state.selectedTask)||0));}}catch{}
  render();
}catch(error){$('#app').innerHTML=`<main class="load-error"><h1>The workspace could not load.</h1><p>${escape(error.message)}</p><a href="./">Try again</a> · <a href="https://github.com/RyanAlberts/pmstack">Open the templates on GitHub</a></main>`;}
